-- A newly-created daily task assigned to a weekly goal also creates its reusable goal task.
-- Existing daily IDs, sessions, paper links and content stay intact. Historical rows are not backfilled implicitly.
CREATE TRIGGER tasks_create_goal_child AFTER INSERT ON tasks WHEN NEW.goal_id IS NOT NULL AND NEW.goal_task_id IS NULL BEGIN INSERT INTO goal_tasks(goal_id,title,status,points,paper_id,paper_ids,plan_id,idea_id,project_id,criteria,note,sort,done_at,created_at,updated_at) SELECT NEW.goal_id,NEW.title,iif(NEW.status='done','done','todo'),NEW.points,NEW.paper_id,NEW.paper_ids,NEW.plan_id,NEW.idea_id,COALESCE(NEW.project_id,g.project_id),NEW.criteria,NEW.note,COALESCE((SELECT MAX(sort)+1 FROM goal_tasks WHERE goal_id=NEW.goal_id),1),NEW.done_at,NEW.created_at,NEW.updated_at FROM goals g WHERE g.id=NEW.goal_id; UPDATE tasks SET goal_task_id=last_insert_rowid() WHERE id=NEW.id; INSERT INTO changes(entity,entity_id,op,field,old,new,actor,origin,created_at) SELECT 'task',NEW.id,'update','goal_task_id',NULL,CAST(goal_task_id AS TEXT),'system','日任务归属周目标时建立子任务',NEW.updated_at FROM tasks WHERE id=NEW.id; END;
CREATE TRIGGER tasks_assign_goal_child AFTER UPDATE OF goal_id ON tasks WHEN NEW.goal_id IS NOT NULL AND NEW.goal_task_id IS NULL BEGIN INSERT INTO goal_tasks(goal_id,title,status,points,paper_id,paper_ids,plan_id,idea_id,project_id,criteria,note,sort,done_at,created_at,updated_at) SELECT NEW.goal_id,NEW.title,iif(NEW.status='done','done','todo'),NEW.points,NEW.paper_id,NEW.paper_ids,NEW.plan_id,NEW.idea_id,COALESCE(NEW.project_id,g.project_id),NEW.criteria,NEW.note,COALESCE((SELECT MAX(sort)+1 FROM goal_tasks WHERE goal_id=NEW.goal_id),1),NEW.done_at,NEW.created_at,NEW.updated_at FROM goals g WHERE g.id=NEW.goal_id; UPDATE tasks SET goal_task_id=last_insert_rowid() WHERE id=NEW.id; INSERT INTO changes(entity,entity_id,op,field,old,new,actor,origin,created_at) SELECT 'task',NEW.id,'update','goal_task_id',NULL,CAST(goal_task_id AS TEXT),'system','日任务归属周目标时建立子任务',NEW.updated_at FROM tasks WHERE id=NEW.id; END;
